SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(o),'identity',to_jsonb(pg_identify_object('pg_opclass'::regclass,o.oid,0)),'owner',pg_get_userbyid(o.opcowner)) ORDER BY o.oid),'[]'::jsonb) AS payload FROM pg_opclass o WHERE o.opcnamespace='public'::regnamespace OR o.oid IN (SELECT unnest(indclass::oid[]) FROM pg_index WHERE indexrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace))) AS capture